code:
terraform {
  required_providers {
    grafana = { source = "grafana/grafana", version = "~> 2.0" }
  }
}

provider "grafana" {
  url  = aws_grafana_workspace.pipeline.endpoint
  auth = var.grafana_service_account_token
}

resource "grafana_folder" "data_platform" {
  title = "Data Platform"
}

resource "grafana_data_source" "cloudwatch" {
  type = "cloudwatch"
  name = "CloudWatch-Pipeline"
  json_data_encoded = jsonencode({
    defaultRegion = "us-east-1"
    authType      = "default"
  })
}

resource "grafana_dashboard" "pipeline_health" {
  folder = grafana_folder.data_platform.id
  config_json = jsonencode({
    title = "S&P Pipeline Health"
    templating = {
      list = [{
        name  = "source"
        type  = "query"
        query = "dimension_values(us-east-1,Pipeline/Orders,RecordsProcessed,Source)"
      }]
    }
    panels = [
      { title = "Records Processed", type = "stat",
        targets = [{ namespace = "Pipeline/Orders", metricName = "RecordsProcessed",
                     dimensions = { Source = "$source" }, statistic = "Sum" }] },
      { title = "Error Rate %", type = "stat" }
    ]
  })
}

resource "grafana_contact_point" "slack" {
  name = "slack-data-platform"
  slack { url = var.slack_webhook_url }
}

resource "grafana_rule_group" "pipeline_alerts" {
  name             = "pipeline-critical"
  folder_uid       = grafana_folder.data_platform.uid
  interval_seconds = 300
  rule { name = "No records processed in 25h"; condition = "C" }
}
